import {
  createRootRouteWithContext,
  createRouter,
  createRoute,
} from '@tanstack/react-router'
import { RouterContext, DashboardRoute } from './routes/dashboard'

const rootRoute = createRootRouteWithContext<RouterContext>()({
  component: () => {
    return (
      <div style={{ fontFamily: 'sans-serif', padding: '2rem' }}>
        <DashboardRoute />
      </div>
    )
  },
})

const dashboardRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/dashboard',
  component: DashboardRoute,
})

const routeTree = rootRoute.addChildren([dashboardRoute])

export const router = createRouter({
  routeTree,
  defaultPreload: 'intent',
})

export type Router = typeof router

import { createServerFn } from '@tanstack/react-start'
import { Suspense, use } from 'react'

// Server function that simulates a slow database query
export const getMetrics = createServerFn({ method: 'GET' }).handler(
  async () => {
    // Simulate a 2-second slow database query
    await new Promise((resolve) => setTimeout(resolve, 2000))

    return {
      revenue: 15000,
      users: 420,
    }
  },
)

function MetricsDisplay({
  promise,
}: {
  promise: Promise<{ revenue: number; users: number }>
}) {
  const metrics = use(promise)
  return (
    <div>
      <p>Revenue: {metrics.revenue}</p>
      <p>Users: {metrics.users}</p>
    </div>
  )
}

export function DashboardRoute() {
  const metricsPromise = getMetrics()

  return (
    <div>
      <h1>Dashboard</h1>
      <Suspense fallback={<div>Loading metrics...</div>}>
        <MetricsDisplay promise={metricsPromise} />
      </Suspense>
    </div>
  )
}

